payload:
$ErrorActionPreference='Continue'
$r='C:\Users\Xxkan\mhw-mods-work-canonical'
if (!(Test-Path $r)) { Write-Output 'ERROR canonical repo missing'; exit 2 }
$env:GIT_TERMINAL_PROMPT='0'
& git -C $r fetch origin --prune '+refs/heads/*:refs/remotes/origin/*' 2>&1 | ForEach-Object { "$_" }
if ($LASTEXITCODE -ne 0) { Write-Output 'ERROR fetch failed'; exit 3 }
$deleted=@(); $kept=@()
foreach($ref in @(& git -C $r for-each-ref --format='%(refname)' refs/remotes/origin/)){
  if($ref -notmatch '^refs/remotes/origin/(.+)$'){ continue }
  $b=$Matches[1]
  if(!$b -or $b -in @('HEAD','main','heaven-bridge')){ continue }
  if($b -like 'agent/bridge-*' -or $b -like 'agent/heaven-hosted-*'){ $kept += "$b|active-lane"; continue }
  $sha0=(& git -C $r rev-parse "origin/$b" 2>$null).Trim()
  if(!$sha0){ $kept += "$b|unresolved"; continue }
  $safe=$false; $reason=''
  & git -C $r merge-base --is-ancestor "origin/$b" origin/main 2>$null
  if($LASTEXITCODE -eq 0){$safe=$true;$reason='ancestor'} else {
    $cherry=@(& git -C $r cherry origin/main "origin/$b" 2>$null)
    if($LASTEXITCODE -eq 0 -and @($cherry|Where-Object{$_ -match '^\+ '}).Count -eq 0){$safe=$true;$reason='patch-equivalent'}
  }
  if(!$safe){$kept += "$b|unique";continue}
  $live=(& git -C $r ls-remote --heads origin "refs/heads/$b" 2>$null)
  if(!$live){$kept += "$b|absent";continue}
  if((($live -split '\s+')[0]) -ne $sha0){$kept += "$b|moved";continue}
  & git -C $r push origin --delete -- $b 2>&1 | ForEach-Object{"$_"}
  if($LASTEXITCODE -eq 0){$deleted += "$b|$reason"}else{$kept += "$b|delete-failed"}
}
& git -C $r fetch origin --prune 2>&1 | ForEach-Object{"$_"}
$remaining=@()
foreach($ref in @(& git -C $r for-each-ref --format='%(refname)' refs/remotes/origin/)){
 if($ref -match '^refs/remotes/origin/(.+)$'){ $b=$Matches[1]; if($b -and $b -notin @('HEAD','main')){$remaining+=$b} }
}
'DELETED_COUNT='+$deleted.Count
$deleted|Sort-Object
'KEPT_COUNT='+$kept.Count
$kept|Sort-Object
'REMAINING_NON_MAIN_COUNT='+$remaining.Count
$remaining|Sort-Object
